<?php
declare(strict_types=1);
namespace Modules\Commande;
use Core\Auth; use Core\Env; use Core\RateLimiter; use Core\Request; use Core\Response; use Core\Validator; use PDO; use Throwable;
final class OrderController {
 public function __construct(private PDO $pdo, private CartController $cart, private Auth $auth) {}
 public function create(): never { $user=$this->auth->requireRoles(['client','vendeur','admin']); RateLimiter::assertAllowed('order:'.Request::ip(),(int)Env::get('ORDER_RATE_LIMIT','10'),(int)Env::get('ORDER_RATE_WINDOW_SECONDS','3600')); $d=(new Validator(Request::json()))->required('customer_name')->required('phone')->phone('phone')->required('address')->required('city_id')->integer('city_id')->required('reception_mode')->in('reception_mode',['retrait','livraison'])->required('payment_method')->in('payment_method',['cash','mobile_money','virement'])->validated(); $items=$this->cart->lines(); if(!$items) Response::error('Le panier est vide.',422); try{$this->pdo->beginTransaction(); $city=$this->pdo->prepare('SELECT id,name,delivery_fee,is_active FROM cities WHERE id=:id FOR UPDATE'); $city->execute(['id'=>(int)$d['city_id']]); $city=$city->fetch(); if(!$city || !(int)$city['is_active']) throw new \RuntimeException('Ville indisponible.'); $total=0; foreach($items as &$line){ $s=$this->pdo->prepare('SELECT pv.id,pv.price,pv.stock_qty,pv.is_available,p.is_active FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE pv.id=:id FOR UPDATE'); $s->execute(['id'=>$line['product_variant_id']]); $v=$s->fetch(); if(!$v || !(int)$v['is_available'] || !(int)$v['is_active'] || (int)$v['stock_qty']<(int)$line['quantity']) throw new \RuntimeException('Stock insuffisant pour un article du panier.'); $line['unit_price']=(float)$v['price']; $total+=(float)$v['price']*(int)$line['quantity']; } unset($line); if($d['reception_mode']==='livraison') $total+=(float)$city['delivery_fee']; $s=$this->pdo->prepare('INSERT INTO orders (customer_name,phone,address,city_id,reception_mode,total,status) VALUES (:name,:phone,:address,:city_id,:mode,:total,\'a_preparer\')'); $s->execute(['name'=>trim($d['customer_name']),'phone'=>trim($d['phone']),'address'=>trim($d['address']),'city_id'=>(int)$city['id'],'mode'=>$d['reception_mode'],'total'=>$total]); $orderId=(int)$this->pdo->lastInsertId(); foreach($items as $line){ $q=(int)$line['quantity']; $s=$this->pdo->prepare('INSERT INTO order_items (order_id,product_variant_id,quantity,unit_price) VALUES (:order_id,:variant_id,:quantity,:unit_price)'); $s->execute(['order_id'=>$orderId,'variant_id'=>$line['product_variant_id'],'quantity'=>$q,'unit_price'=>$line['unit_price']]); $s=$this->pdo->prepare('UPDATE product_variants SET stock_qty=stock_qty-:quantity WHERE id=:id'); $s->execute(['quantity'=>$q,'id'=>$line['product_variant_id']]); } $s=$this->pdo->prepare('INSERT INTO order_status_history (order_id,status,changed_by) VALUES (:order_id,\'a_preparer\',:changed_by)'); $s->execute(['order_id'=>$orderId,'changed_by'=>$user['id']]); $s=$this->pdo->prepare('INSERT INTO payments (order_id,status,method) VALUES (:order_id,\'en_attente\',:method)'); $s->execute(['order_id'=>$orderId,'method'=>$d['payment_method']]); $this->pdo->commit(); $_SESSION['cart']=[]; $order=['id'=>$orderId,'total'=>$total,'city_name'=>$city['name'],'reception_mode'=>$d['reception_mode']]; Response::success(['order'=>$order,'whatsapp_url'=>WhatsAppService::link($order,$items)],'Commande créée.',201); }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack(); if($e instanceof \RuntimeException)Response::error($e->getMessage(),422); throw $e;} }
 public function whatsapp(array $p): never { $this->auth->requireRoles(['client','vendeur','admin']); $s=$this->pdo->prepare('SELECT o.id,o.total,o.reception_mode,c.name AS city_name FROM orders o JOIN cities c ON c.id=o.city_id WHERE o.id=:id');$s->execute(['id'=>(int)$p['id']]);$o=$s->fetch();if(!$o)Response::error('Commande introuvable.',404);$s=$this->pdo->prepare('SELECT p.name,pv.composition,pv.flavor,pv.format,oi.quantity,oi.unit_price FROM order_items oi JOIN product_variants pv ON pv.id=oi.product_variant_id JOIN products p ON p.id=pv.product_id WHERE oi.order_id=:id');$s->execute(['id'=>(int)$p['id']]);Response::success(['whatsapp_url'=>WhatsAppService::link($o,$s->fetchAll())],'Lien WhatsApp généré.'); }
 public function mine(): never { $user=$this->auth->requireRoles(['client']); $s=$this->pdo->prepare('SELECT o.id,o.total,o.reception_mode,o.status,o.created_at,c.name AS city_name FROM orders o JOIN cities c ON c.id=o.city_id WHERE o.phone=:phone ORDER BY o.created_at DESC');$s->execute(['phone'=>$user['phone']]);Response::success($s->fetchAll(),'Historique des commandes.'); }
}
